starter:
function fullName(first, last) {
  // your code here
}

console.log(fullName("Ana", "López"));

solution:
function fullName(first, last) {
  // Inside backticks, each ${ } is replaced by the value of the variable.
  // The space between the two ${ } is part of the text.
  return `${first} ${last}`;
}

console.log(fullName("Ana", "López"));

alternatives:
function fullName(first, last) {
  return first + " " + last;
}

console.log(fullName("Ana", "López"));

starter:
function initials(text) {
  // your code here
}

console.log(initials("Ana López"));

solution:
function initials(text) {
  // split(" ") cuts the text at the space: ["Ana", "López"]
  let words = text.split(" ");
  // charAt(0) is the first letter of each word.
  return words[0].charAt(0) + "." + words[1].charAt(0) + ".";
}

console.log(initials("Ana López"));

alternatives:
function initials(text) {
  let words = text.split(" ");
  return `${words[0][0]}.${words[1][0]}.`;
}

console.log(initials("Ana López"));

