  // your code here
}

console.log(sumStrings("2", "3"));

solution:
function sumStrings(a, b) {
  // With strings, + would join them ("2" + "3" is "23").
  // Number() converts each text into a number first.
  return Number(a) + Number(b);
}

console.log(sumStrings("2", "3"));

alternatives:
function sumStrings(a, b) {
  return parseFloat(a) + parseFloat(b);
}

