starter:
function describeType(value) {
  // your code here
}

console.log(describeType(null));

solution:
function describeType(value) {
  // typeof null is "object" (an old bug), so null is checked first.
  if (value === null) {
    return "null";
  }
  // Arrays are objects too; instanceof Array tells them apart.
  if (value instanceof Array) {
    return "array";
  }
  return typeof value;
}

console.log(describeType(null));

alternatives:
function describeType(value) {
  if (value === null) {
    return "null";
  }
  if (Array.isArray(value)) {
    return "array";
  }
  return typeof value;
}

console.log(describeType(null));

