function addToBig(big, n) {
  // your code here
}

console.log(addToBig(10n, 5));

solution:
function addToBig(big, n) {
  // big + n would throw a TypeError (BigInt and number can't be mixed),
  // so n is converted to a BigInt first.
  return big + BigInt(n);
}

console.log(addToBig(10n, 5));

