function fileExtension(file) {
  // your code here
}

console.log(fileExtension("photo.png"));

solution:
function fileExtension(file) {
  // "backup.tar.gz".split(".") gives ["backup", "tar", "gz"].
  let parts = file.split(".");
  // The last element is at position length - 1.
  return parts[parts.length - 1];
}

console.log(fileExtension("photo.png"));

alternatives:
function fileExtension(file) {
  let parts = file.split(".");
  return parts.pop();
}

console.log(fileExtension("photo.png"));

