solution:
function moveFirstToEnd(list) {
  // shift() removes the first element and returns it...
  let first = list.shift();
  // ...and push() adds it at the end.
  list.push(first);
  return list;
}

console.log(moveFirstToEnd([1, 2, 3]));

alternatives:
function moveFirstToEnd(list) {
  list.push(list.shift());
  return list;
}

