function mirror(list) {
  // your code here
}

let nums = [1, 2];
console.log(mirror(nums).length, nums[0]);

solution:
function mirror(list) {
  // reverse() changes the array it is called on,
  // so we reverse a copy made with slice().
  let reversed = list.slice().reverse();
  // concat() returns a new array and leaves list untouched.
  return list.concat(reversed);
}

let nums = [1, 2];
console.log(mirror(nums).length, nums[0]);

alternatives:
function mirror(list) {
  let copy = list.concat();
  copy.reverse();
  return list.concat(copy);
}

let nums = [1, 2];
console.log(mirror(nums).length, nums[0]);

starter:
function makeProduct(name, price) {
  // your code here
}

console.log(makeProduct("pen", 2));

solution:
function makeProduct(name, price) {
  // An object literal: each property is key: value.
  // inStock is the boolean true, not the string "true".
  return {
    name: name,
    price: price,
    inStock: true,
  };
}

console.log(makeProduct("pen", 2));

alternatives:
function makeProduct(name, price) {
  let product = {};
  product.name = name;
  product.price = price;
  product.inStock = true;
  return product;
}

console.log(makeProduct("pen", 2));

