function removeKey(obj, key) {
  // your code here
}

console.log(removeKey({ a: 1, b: 2 }, "a"));

solution:
function removeKey(obj, key) {
  // Square brackets use the VALUE of key (for example "a").
  // obj.key would look for a property literally called "key".
  delete obj[key];
  return obj;
}

console.log(removeKey({ a: 1, b: 2 }, "a"));
